#include "allmref_buffer_common.h"
extern "C" __device__ __noinline__ void c16_record_mref(int pred,uint64_t addr,uint32_t idx,uint64_t bp,uint64_t cp,uint64_t cap){ unsigned m=__ballot_sync(__activemask(),pred); if(!m)return; unsigned lane=threadIdx.x&31; if(lane!=(unsigned)(__ffs(m)-1))return; C16Ctr*c=(C16Ctr*)cp; unsigned long long n=atomicAdd(&c->count,1ULL); if(n>=cap){atomicAdd(&c->overflow,1ULL);return;} C16Rec&r=((C16Rec*)bp)[n];r.static_index=idx;r.active_mask=m; for(int i=0;i<32;i++)r.addr[i]=__shfl_sync(m,addr,i);}
